"import { useEffect } from "react";
import { useRouter } from "expo-router";
import { HzSplashScreen } from "../components/haazir/auth/HzSplashScreen";
import { useAuth } from "../lib/AuthContext";

export default function Index() {
  const router = useRouter();
  const { session, user, loading } = useAuth();

  useEffect(() => {
    if (loading) return;

    // Timeout of 1400ms to perfectly show exactly 1 iteration of the short animation
    const timer = setTimeout(() => {
      if (!session) {
        router.replace("/(auth)/role-select");
      } else if (user) {
        if (user.role === "provider") {
          router.replace(user.isOnboarded ? "/(provider)/dashboard" : "/(provider)/onboarding");
        } else {
          router.replace("/(consumer)/home");
        }
      }
    }, 1400);

    return () => clearTimeout(timer);
  }, [loading, session, user, router]);

  return <HzSplashScreen />;
}"

